package ledger

// Ledger keeps sales, restocks and credit in one SQLite file. Every change is an append-only
// entry, so a sync can replay what the server has not seen.
type Ledger struct{}

func Open(path string) (*Ledger, error) { return &Ledger{}, nil }
func (l *Ledger) Close() error { return nil }

